rows=[]
for f in C['forms']:
 s=CS[f['sourceIds'][0]];v=f.get('version',{});v='; '.join(str(x)for k,x in v.items()if k in ['printed','fileNameRevision','formDate','printedDate'] and x)if isinstance(v,dict)else str(v)
 req={'required':'Required at its applicable stage','conditional':'Conditional to route, request or grant','recommended':'Recommended evidence gathering','optional_template':'Template optional; underlying document may be required'}.get(f.get('requiredness'),'Conditional')
 if f.get('scope')in['operating','optional_opening_grant']:req='Optional grant / operating claim; not initial licensing'
 if f['id']=='parent_handbook':req='Required handbook; current instructions say use template'
 rows.append([e(f['title'])+('<small>'+e(v)+'</small>'if v else''),e(req),'<span class="status">Mapped for digital form</span>',link(s,'Official form / template')])
parts+=['<details><summary>Centre forms and related claims · 22 form/template families</summary>'+table(['Form / version','When used','Mapping status','Official source'],rows)+'</details>']
rows=[]
for f in H['notPublicOrNoStandardFormLocated']:
 labels={'learning_plans':('Applicant Learning Plans','Ministry provides plans during sessions.'),'alternate_outdoor_play_plan':('Alternate outdoor play plan','If suitable on-property outdoor space cannot be provided.'),'criminal_information_disclosure_consent':('Criminal-check disclosure consent','Required adult consent is distinct from contact-information release.'),'fee_schedule':('Standalone official home fee-schedule blank','Written schedule required; provider draft can be prepared and confirmed.'),'inspection_templates':('Universal home inspection blank','Qualified authority issues report; no self-certification.'),'grant_decline':('Standalone grant-decline form','Track choice; consultant confirms the actual record needed.')}
 title,why=labels[f['id']];rows.append([e(title),'Home / group home',e(why),'<span class="status blocked">Current template or direction needed</span>'])
for f in C['unavailableForms']:
 rows.append([e(f['title']),'Centre',e('Conditional funding or operating request.'if f.get('scope')=='optional_funding_or_operations'else'Exact public blank not verified; request current Ministry direction.'),'<span class="status blocked">Current template or direction needed</span>'])
parts+=['<details><summary>Forms or templates not fully available publicly</summary><p class="small">These items are not presented as converted official forms. Some are case-specific agreements, outside reports or applicant-authored documents. A missing optional grant form does not make a licence application incomplete.</p>'+table(['Item','Applies to','Treatment','Status'],rows)+'<p class="sources">'+refs(['apply-page','faq','regulations'],HS)+'<br>'+refs(['opening-checklist','licensing-manual'],CS)+'</p></details>']
parts+=['<details><summary>Current version cautions</summary><ul><li><strong>New group homes start at up to 12.</strong> Existing eligible group homes may apply to expand to 16; the two-year regular-licence and other approval conditions matter.</li><li><strong>Home self-assessment still prints 40 hours of ECE training.</strong> Current regulation 61 requires a 45-hour introductory course or approved equivalent within one year; group providers need ECE I within three years, subject to applicable exceptions.</li><li><strong>Current centre CNA is four pages.</strong> An older indexed three-page copy omits newer readiness questions. Use the live official link.</li><li><strong>Centre licence form is still EY10/2021.</strong> Current regulation determines conditional incorporation, lease and ownership evidence. The form lacks a municipality-specific signature label.</li><li><strong>Funding versions vary.</strong> Current tuition form is EY02/2026; PD application is2026–27, while its general information sheet remains2025–26. Confirm corresponding-year conditions before claiming.</li><li><strong>Current direct-deposit form is Rev12/23.</strong> Certified or auditable electronic signatures are accepted by its instructions; this does not waive original police-check requirements.</li></ul><p class="sources">'+refs(['home-application','group-update','self-assessment','regulations','deposit'],HS)+'<br>'+refs(['cna','licence'],CS)+'</p></details></section>']
parts+=['<section id="ownership"><h2>Who supplies and reviews the evidence</h2>',table(['Owner','Completes or supplies','Proposed handling'],[
 ['Applicant / organization','Facility details, development rationale, budgets, policies, menus, relevant declarations and corrections.','Save answers once, review any reused information and submit a version.'],
 ['Reference / other adult','Reference’s own assessment; adult consent where required.','Keep separate ownership and privacy. Applicant cannot write a favourable reference on someone’s behalf.'],
 ['Police / RCMP','Criminal-record and vulnerable-sector checks.','Track original sealed-envelope handling for the initial home package. A scan is not a replacement.'],
 ['Fire, health and heating authorities','Actual inspection findings and deficiencies. Public-health report is a centre requirement; do not add it universally to a home package.','Track booking, issuer, report and remediation. Applicant does not approve a pass.'],
 ['Insurer, bank, registry, property owner','Insurance, banking confirmation, incorporation, lease and applicable premises permission.','Store or reference authentic evidence; preserve certification/signature requirements.'],
 ['Training provider / certification authority','First aid, CPR, ECE qualification or enrolment and workshop evidence.','Track role-specific requirements and deadlines; not all training is required before initial licensing.'],
 ['Consultant / Ministry','Local-need assessment, suitability and compliance review, correction requests, recommendations and licence/funding decisions.','Staff-only review fields and auditable decisions. Separate “received” from “accepted”.']]),'<p class="sources">'+refs(['home-application','regulations','deposit','reference'],HS)+'<br>'+refs(['licensing-manual','licence','opening-checklist'],CS)+'</p></section>']
parts+=['<section id="limits"><h2>Timing, boundaries and unresolved details</h2><div class="two"><div><h3>Published expectations</h3><p>The home FAQ says applicants should hear from staff within 10 business days and describes an average licensing time of three to five months. Local-need screening can affect whether an application proceeds; a name may be kept on file for up to three months in a well-served area.</p><p>Centre applications remain open year-round, with development approvals focused on greatest need. The final-meeting instruction is at least four weeks before anticipated opening. No fixed total centre processing guarantee was verified.</p><p class="sources">'+refs(['faq','apply-page'],HS)+'<br>'+refs(['centre-apply','opening-checklist'],CS)+'</p></div><div><h3>Before using this in production</h3><p>Confirm current consultant forms, local approval requirements, accepted electronic submissions and signatures, and the exact integration with existing fee/enrolment systems. Validate current grant conditions and any source-version conflicts.</p><p>The proposed four stages organize the experience; they are not claimed to be official Ministry stage names. Form mapping does not decide suitability, grant eligibility or regulatory compliance.</p><p>Banking, household/health details, police checks, references and signatures need controlled handling. Drafting assistance should avoid these records and should never score applicant suitability.</p></div></div><div class="note attention"><p><strong>Grants are conditional.</strong> Home fire/health/safety funding is generally paid after fire inspection and before opening; start-up funding follows licence issuance. Active Play requires a licensed home; Play and Exploration requires the home provider’s Phase I evidence. Centre development grants need separate approvals. Ask for approval before purchases where the programme requires it.</p><p class="sources">'+refs(['grants-guidance','active-info','play-info'],HS)+'<br>'+refs(['centre-apply'],CS)+'</p></div></section><footer><p>Prepared from current official Saskatchewan web pages, publication catalogues, forms and regulations. Public source links above allow direct checking. The map does not submit an application or issue an approval.</p></footer></main></body></html>']
out.parent.mkdir(exist_ok=True);out.write_text(''.join(parts));print(out,len(out.read_text()))
